    name = 'sorted_support_insert'
    priority = 80

    def allowed(self, partial, memory, candidates):
        allowed = []
        for a in candidates:
            so, sd = (a.so, a.sd)
            if not partial.is_sorted_stack(sd):
                continue
            if partial.g(so) <= partial.g(sd):
                allowed.append(a)
